class Ticket04 {final int id,floor,slot;final String reg;Ticket04(int i,String r,int f,int s){id=i;reg=r;floor=f;slot=s;}Ticket04(int i,String r){this(i,r,-1,-1);}static Ticket04 visitor(int i,String r,int f,int s){return new Ticket04(i,r,f,s);}public String toString(){return "Ticket#"+id+" "+reg+" @("+floor+","+slot+")";}} public class Task04Demo {public static void main(String[]x){System.out.println(new Ticket04(101,"TN01AA1111",0,4));System.out.println(new Ticket04(102,"TN02BB2222"));System.out.println(Ticket04.visitor(103,"TN03CC3333",1,2));System.out.println("Constructor chaining initializes fields immediately.");}}